    )
    parser.add_argument(
        "--include-resolved",
        action="store_true",
        help="Include review suggestions that have been marked as resolved (default: filter them out)",
    )
    parser.add_argument(
        "--all-reviews",
        action="store_true",
        help="Extract all CodeRabbit reviews (default: latest only)",
    )
    parser.add_argument(
        "--since-commit",
        metavar="SHA",
        help="Extract reviews submitted after this commit SHA",
    )
    parser.add_argument(
