        print("=" * 40)
        print()
        print("WHAT THIS DOES:")
        print(
            "  Converts CodeRabbit GitHub PR reviews into clean text for AI coding agents"
        )
        print("  (Claude, ChatGPT, etc.) to automatically apply code suggestions.")
