            }
            pageInfo {
              hasNextPage
              endCursor
            }
          }
        }
      }
    }
    """

    try:
        # Use gh api to make GraphQL request with pagination
        import json

        all_threads = []
        cursor = None
        has_next_page = True
        page_count = 0

        while has_next_page:
            page_count += 1

            # Build command with cursor if available
            cmd = [
